pub fn median(values: &[i64]) -> Option<f64> {
    let mut sorted = values.to_vec();
    sorted.sort();

    let n = sorted.len() as i128;
    if n == 0 {
        return None;
    }

    let middle = (n - 1) / 2;
    if n % 2 == 1 {
        Some(sorted[middle as usize] as i128 / 2.0)
